.PHONY: help check validate parity install clean

PYTHON ?= python

help:  ## Show this help
	@grep -E '^[a-zA-Z_-]+:.*?## .*$$' $(MAKEFILE_LIST) \
		| awk 'BEGIN {FS = ":.*?## "}; {printf "  \033[36m%-12s\033[0m %s\n", $$1, $$2}'

check: validate parity  ## Run everything CI runs

validate:  ## Validate SKILL.md frontmatter, cross-references, and links
	$(PYTHON) scripts/validate_skills.py --strict

parity:  ## Every skill must be listed in every README
	$(PYTHON) scripts/check_readme_parity.py

install:  ## Symlink the skills into ~/.claude/skills for local testing
	@mkdir -p $(HOME)/.claude/skills
	@ln -sfn $(CURDIR)/skills $(HOME)/.claude/skills/oss-skills
	@echo "linked $(CURDIR)/skills -> $(HOME)/.claude/skills/oss-skills"

clean:  ## Remove Python caches
	@find . -name __pycache__ -type d -exec rm -rf {} + 2>/dev/null || true
